using Test, Topology
isdefined(@__MODULE__, :vl_example) || include(joinpath(@__DIR__, "../examples/VLExample.jl"))

@testset "U(R) MST exact interface" begin
    H = URAlgebra()
    # Independent manifold orders, not values generated by the implementation.
    for (name, order) in (("s3_abalone",1), ("lens_2_1",2),
                          ("lens_3_2",3), ("lens_3_1_mst2_example23",3), ("poincare",1))
        v = vl_example(name)
        z = Z_MST(v,H)
        @test ur_prime_invariant(v) == z
        @test abs(z) == 1//BigInt(order)
        before = deepcopy(v)
        x = invariant_expression(v,H)
        @test evaluate_invariant(simplify_invariant(x;strategy=:none)) == z
        @test v.gauss == before.gauss && v.weights == before.weights
        for k in eachindex(only(v.gauss))
            shifted = deepcopy(v); cyclic_shift!(shifted,1,k)
            @test Z_MST(shifted,H) == z
        end
    end
    v = vl_example("s3_abalone")
    for n in 1:5
        if n > 1
            code, signs = real_gauss_code(v)
            offset = length(signs)+1
            bridge = [sign(x)*offset+x for x in [-2,-1,1,4,-4,-3,3,2]]
            word = vcat(bridge[1:4], [offset,-offset], bridge[5:8], only(code))
            set_data!(v;rgauss=[word],orientation=vcat(signs,[1,-1,1,-1,1]))
        end
        @test first(is_closed(v))
        @test Z_MST(v,H) == (-1)^n//BigInt(1)
    end
    @test_throws ArgumentError Z_MST(v,H;strategy=:unknown)
    @test_throws DomainError evaluate_invariant(URMSTExpression(zeros(BigInt,1,1)))
    # The trace matrix has rank deficit b1 here, so no finite value exists.
    for name in ("s2xs1", "s2xs1_2vertex", "koda_fig13")
        @test_throws DomainError Z_MST(vl_example(name),H)
    end
    two = VirtualLink(); set_data!(two;rgauss=[[1,-1],[2,-2]],orientation=[1,1])
    @test_throws ArgumentError Z_MST(two,H)
    base = vl_example("s3_abalone")
    z = Z_MST(base,H); solve_integer_weights(base;assign=true)
    weights = deepcopy(base.weights)
    @test Z_MST(base,H) == z
    @test base.weights == weights
end
